#define main connectivity_sweep_main
#include "cave-connectivity-judge.cpp"
#undef main
#include "game/world_generation/terrain_mesh.cpp"
using namespace altaria;
struct Volumes {
 const Generator&g;std::shared_ptr<EditMap> edits=std::make_shared<EditMap>();std::shared_ptr<AppearanceMap> surfaces=std::make_shared<AppearanceMap>();
 struct Entry{std::shared_ptr<Volume> volume;uint64_t used;};std::unordered_map<IVec3,Entry,CoordHash> data;uint64_t clock=0;size_t builds=0,peak=0;
 explicit Volumes(const Generator&gen):g(gen){}
 BlockId at(int x,int y,int z){if(y<g.settings().min_y||y>=g.settings().max_y)return g.blocks().air;IVec3 key{int(std::floor(double(x)/32))*32,0,int(std::floor(double(z)/32))*32};auto found=data.find(key);if(found==data.end()){if(data.size()>=48){auto oldest=data.begin();for(auto it=data.begin();it!=data.end();++it)if(it->second.used<oldest->second.used)oldest=it;data.erase(oldest);}StageTimings t;auto v=make_volume({key.x,key.z,0},g,edits,surfaces,t);found=data.emplace(key,Entry{std::move(v),0}).first;builds++;peak=std::max(peak,data.size());}found->second.used=++clock;return found->second.volume->at(x-key.x,y-g.settings().min_y,z-key.z);}
};
static bool run_real(const Generator&g,Volumes&volumes,Network primitive,Bounds bounds,Point from,Point to,bool full,size_t&visited,size_t&solid_blocks,size_t&water){auto isolated=query(std::move(primitive));Lattice grid(expanded(bounds));std::vector<float> xs,zs;xs.reserve(size_t(grid.nx)*grid.nz);zs.reserve(xs.capacity());for(int iz=0;iz<grid.nz;iz++)for(int ix=0;ix<grid.nx;ix++){xs.push_back(float(grid.x0+ix));zs.push_back(float(grid.z0+iz));}auto cols=g.columns(xs,zs);Air air=[&](int x,int y,int z){auto&c=cols[size_t(z-grid.z0)*grid.nx+x-grid.x0];if(!g.underground()->sample(isolated,x,y,z,c.height).carved)return false;auto b=volumes.at(x,y,z);if(g.blocks().get(b).solid){solid_blocks++;return false;}water+=g.blocks().get(b).water;return true;};bool ok=grid.flood(from,to,air,full);visited+=grid.queue.size();if(full){size_t count=0;for(int z=grid.z0;z<grid.z0+grid.nz;z++)for(int y=grid.y0;y<grid.y0+grid.ny;y++)for(int x=grid.x0;x<grid.x0+grid.nx;x++)count+=air(x,y,z);if(count!=grid.queue.size()){std::cout<<"REAL_ROOM_COMPONENTS carved="<<count<<" reached="<<grid.queue.size()<<std::endl;return false;}}return ok;}
int main(){Registry r;std::string error;const char*ids[]={"air","stone","dirt","grass","sand","water","snow","bedrock"};for(int i=0;i<8;i++){BlockDef b;b.id=i;b.key=ids[i];b.solid=i!=0&&i!=5;b.water=i==5;if(!r.add(b,error))return 2;}Settings cfg;cfg.min_y=-448;cfg.max_y=320;cfg.vegetation=false;cfg.caves.enabled=true;cfg.caves.plan.infernal_chance=1;cfg.caves.plan.entrance_chance=1;Generator g(cfg,r,1337);Volumes volumes(g);size_t tested=0,rooms=0,visited=0,solid=0,water=0;std::unordered_set<uint64_t> seen;
for(auto region:{Region{0,0},Region{-1,-1}}){auto owner=g.underground()->region(region);if(!owner||!owner->network.valid)return 3;auto&n=owner->network;std::unordered_set<uint64_t> local;for(auto&c:n.chambers)local.insert(c.id);std::unordered_set<std::string> selected;
for(auto&p:n.passages){std::string type=p.entrance?"entrance":p.vertical?"shaft":(!local.count(p.a)||!local.count(p.b))?"cross_region":"local";if(!selected.insert(type).second||!seen.insert(p.id).second)continue;Network primitive;primitive.valid=true;primitive.passages={p};if(!run_real(g,volumes,std::move(primitive),bounds(p),p.from,p.to,false,visited,solid,water)){std::cout<<"REAL_PASSAGE_DISCONNECTED region="<<region.x<<","<<region.z<<" id="<<p.id<<" type="<<type<<" radius="<<p.radius<<std::endl;return 1;}tested++;std::cout<<"REAL_EDGE_PASS region="<<region.x<<","<<region.z<<" id="<<p.id<<" type="<<type<<" from="<<p.from[0]<<","<<p.from[1]<<","<<p.from[2]<<" to="<<p.to[0]<<","<<p.to[1]<<","<<p.to[2]<<std::endl;}
for(auto&c:n.chambers)if((rooms==0&&c.archetype=="giant")||(rooms==1&&c.archetype=="normal")){Network primitive;primitive.valid=true;primitive.chambers={c};if(!run_real(g,volumes,std::move(primitive),bounds(c),c.center,c.center,true,visited,solid,water)){std::cout<<"REAL_CHAMBER_DISCONNECTED id="<<c.id<<" archetype="<<c.archetype<<std::endl;return 1;}rooms++;std::cout<<"REAL_CHAMBER_PASS id="<<c.id<<" archetype="<<c.archetype<<std::endl;}}
std::cout<<"REAL_GENERATOR_CONNECTIVITY_PASS seed=1337 bounds=-448..320 edges="<<tested<<" rooms="<<rooms<<" voxel_visits="<<visited<<" volume_builds="<<volumes.builds<<" peak_retained_volumes="<<volumes.peak<<" field_candidates_remaining_solid="<<solid<<" water_visits="<<water<<std::endl;return tested>=6&&rooms>0?0:4;}
